#include <iostream>
#include <string>
using namespace std;

int findDay(const string& day) {
    if (day == "monday") return 1;
    if (day == "tuesday") return 2;
    if (day == "wednesday") return 3;
    if (day == "thursday") return 4;
    if (day == "friday") return 5;
    if (day == "saturday") return 6;
    if (day == "sunday") return 7;
    return -1;
}

int main() {
    string day1, day2;
    cin >> day1 >> day2;

    int difference = (findDay(day2) - findDay(day1) + 7) % 7;

    cout << (difference == 0 || difference == 2 || difference == 3 ? "YES" : "NO");

    return 0;
}

